@page "/dashboard"
@using sv_860c31f95a8446c288922e0c476c0390.Services
@rendermode InteractiveServer
@implements IDisposable
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-4">
    <div class="card-header">
        <h5 class="mb-0">@WarehouseState.CurrentWarehouseName</h5>
    </div>
    <div class="card-body">
        <div class="row">
            <div class="col-md-4">
                <div class="card text-bg-@(AlertService.CurrentLowStockCount > 5 ? "danger" : AlertService.CurrentLowStockCount > 0 ? "warning" : "success")">
                    <div class="card-body text-center">
                        <h2>@AlertService.CurrentLowStockCount</h2>
                        <p class="mb-0">Low Stock Alerts</p>
                    </div>
                </div>
            </div>
            <div class="col-md-8">
                <p class="text-muted">
                    Monitoring <strong>@WarehouseState.CurrentWarehouseName</strong> for items below minimum stock levels.
                    Data refreshes every 10 seconds.
                </p>
                <p class="text-muted mb-0">
                    <small>Warehouse ID: @WarehouseState.CurrentWarehouseId</small>
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnStateChanged;
        AlertService.OnAlertCountChanged += OnAlertChanged;
        AlertService.StartPolling();
    }

    private void OnStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private async Task OnAlertChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= OnStateChanged;
        AlertService.OnAlertCountChanged -= OnAlertChanged;
        AlertService.StopPolling();
    }
}

